using Marrow.Core.Port.MultiAccount.Handshake;
using Marrow.Core.Tests.Fixtures;
using Xunit;
namespace Marrow.Core.Tests.Port.MultiAccount.Handshake;
// PORT-ONLY: page :3069-3160, generated by running its JS, not values taken from the port.
public sealed class HandshakeGeometryTests
{
    [Fact, Trait("Rule","R-TEST-4")]
    public void Both_theme_and_Reduce_Motion_samples_equal_the_locked_page_JS()
    {
        foreach(var sample in HandshakeGeometryReference.Cases)
        {
            var actual=HandshakeFrameSamples.Of(HandshakeGeometry.Draw(420,160,sample.Time,sample.Dark,sample.Reduce));
            Assert.Equal(sample.Values.Length,actual.Length);
            for(var i=0;i<actual.Length;i++) Assert.True(Math.Abs(sample.Values[i]-actual[i])<1e-10,$"t={sample.Time}, dark={sample.Dark}, reduce={sample.Reduce}, i={i}: {sample.Values[i]:R} / {actual[i]:R}");
        }
    }
    [Fact, Trait("Rule","R-TEST-4")]
    public void Reduce_Motion_has_only_the_static_arc_and_ghost_with_no_filament_or_pulse_motion()
    {
        var frame=HandshakeGeometry.Draw(420,160,3400,true,true);
        Assert.Single(frame.Strokes);Assert.Empty(frame.Glows);Assert.Equal(31,frame.Strokes[0].Points.Count);
        Assert.Equal(302,frame.Ghost.X);Assert.Equal(78,frame.Ghost.Y);Assert.Equal(1,frame.Ghost.Scale);
    }
}
